5 | async function walk(p:Page,x:number){const end=Date.now()+25000;let jump=0;for(;;){if(Date.now()>end)throw Error(`Cannot reach ${x}: ${JSON.stringify(await read(p))}`);const s=await read(p);if(!s.player){await p.waitForTimeout(50);continue;}if(Math.abs(s.player.x-x)<12)break;const key=s.player.x<x?'d':'a';await p.keyboard.up(key==='d'?'a':'d');await p.keyboard.down(key);if(Date.now()-jump>430){await p.keyboard.press('ArrowUp');jump=Date.now();}await p.waitForTimeout(60);}await p.keyboard.up('a');await p.keyboard.up('d');await expect.poll(async()=>!!(await read(p)).player?.grounded).toBe(true);}

